"""Chunked generation driver for the ALIAS probe — the harness ALIAS-001/002 actually used.

    python probe/generate_alias.py --model <core> --label alias_B \
        --prompts <records>/alias001-20260918/render/prompts.jsonl \
        --out <records>/alias001-20260918/gen-B

**Why this file exists.** ALIAS-001 and ALIAS-002 were generated by an ad-hoc scratchpad script
that was never committed. Every arm's `GENERATE.json` records the chunking and the merge checks,
so the *procedure* survived, but the code did not — which is precisely the failure this
programme has already written down twice (AGENDA, process lesson 1: put the number in a script,
not in prose; and `deep-any`'s unreproducible parser). This is the reconstruction, and
`--verify-against` exists so the reconstruction can be *proven* equivalent rather than asserted.

## Why chunked

`stage2_generate.py` leaks across rows on this host: 64 rows succeed and 128 fail at 7449 MiB
free VRAM. The eight longest prompts succeed alone and rows 64:128 succeed as their own file, so
it is neither prompt length nor a poisoned item. Each chunk is a **fresh process** with identical
model, prompts, decoding, dtype and limits; only process boundaries differ. The generator itself
is invoked **unmodified** — this driver never edits it, it only slices the prompts file.

## What it records that the original did not

`GENERATE.json` recorded `transformers` but not `torch`, and not the interpreter. Matched
conditions are the whole basis of a paired contrast, so an unrecorded dependency is an
unfalsifiable claim of matching. This driver records torch, the CUDA build, the interpreter path
and the generator's SHA-256 into `GENERATE.json` alongside the original fields.

## The merge checks, which are assertions and not warnings

  * no duplicate ids
  * merged id order equals the prompts file order exactly
  * every chunk returned exactly as many predictions as it was given prompts
  * generated-token stats RECOMPUTED from the merged predictions, never averaged across chunks

Any failure raises. A merge that silently drops or reorders rows would corrupt a paired contrast
in the one way scoring cannot detect.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import shutil
import subprocess
import sys
import time
from pathlib import Path


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for blk in iter(lambda: f.read(1 << 20), b""):
            h.update(blk)
    return h.hexdigest()


def read_jsonl(p: Path) -> list[dict]:
    return [json.loads(l) for l in p.read_text(encoding="utf-8").splitlines() if l.strip()]


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--model", required=True)
    ap.add_argument("--label", required=True)
    ap.add_argument("--prompts", type=Path, required=True)
    ap.add_argument("--out", type=Path, required=True)
    ap.add_argument("--generator", type=Path, required=True,
                    help="path to stage2_generate.py; invoked unmodified")
    ap.add_argument("--python", default=sys.executable,
                    help="interpreter for the generator; must be the CUDA venv")
    ap.add_argument("--chunk", type=int, default=64)
    ap.add_argument("--max-new-tokens", type=int, default=24)
    ap.add_argument("--max-context", type=int, default=4096)
    ap.add_argument("--dtype", choices=("bf16", "fp32"), default="fp32")
    ap.add_argument("--limit", type=int, default=None,
                    help="first N prompts only -- for harness validation, never for a result")
    ap.add_argument("--verify-against", type=Path, default=None,
                    help="an existing predictions.jsonl; assert byte-equal predictions and "
                         "report rather than write a result")
    ap.add_argument("--no-lease", action="store_true",
                    help="skip the host-RAM lease. Only for a verify pass or a box known quiet.")
    a = ap.parse_args(argv)

    if a.out.exists():
        raise SystemExit(f"create-only output: {a.out} exists")

    # Host RAM is the binding constraint on this box, not VRAM, and two sessions share it.
    # The lease refuses on a LIVE owner and clears a STALE one with a backup -- a stale lease
    # is otherwise indistinguishable from a held one and deadlocks both sessions against a
    # corpse. It also refuses on low free RAM, because a free lease is not a quiet machine.
    lease_token = None
    if not a.no_lease:
        sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "method"))
        import lease as _lease  # noqa: PLC0415
        got = _lease.acquire(label=f"generate_alias:{a.label}")
        lease_token = got["token"]
        if got["cleared_stale"]:
            print(f"[lease] cleared a STALE lease: {got['cleared_stale']}", flush=True)
        print(f"[lease] acquired, {got['free_gib_at_acquire']} GiB free", flush=True)

    rows = read_jsonl(a.prompts)
    if a.limit:
        rows = rows[:a.limit]
    if not rows:
        raise SystemExit("no prompts")

    work = a.out.parent / f".{a.out.name}.chunks"
    if work.exists():
        shutil.rmtree(work)
    work.mkdir(parents=True)

    started = time.time()
    per_chunk, merged = [], []
    n_chunks = (len(rows) + a.chunk - 1) // a.chunk
    for ci in range(n_chunks):
        sl = rows[ci * a.chunk:(ci + 1) * a.chunk]
        cp = work / f"c{ci}.prompts.jsonl"
        with cp.open("w", encoding="utf-8", newline="\n") as f:
            for r in sl:
                f.write(json.dumps(r, ensure_ascii=False) + "\n")
        cout = work / f"c{ci}"
        t0 = time.time()
        # Fresh process per chunk. This is the point of the whole driver.
        cmd = [a.python, str(a.generator), "--model", a.model,
               "--label", f"{a.label}_c{ci}", "--prompts", str(cp), "--out", str(cout),
               "--max-new-tokens", str(a.max_new_tokens),
               "--max-context", str(a.max_context), "--dtype", a.dtype]
        print(f"[chunk {ci}/{n_chunks - 1}] {len(sl)} rows", flush=True)
        r = subprocess.run(cmd, capture_output=True, text=True)
        if r.returncode != 0:
            sys.stderr.write(r.stdout[-4000:] + "\n" + r.stderr[-4000:] + "\n")
            raise SystemExit(f"chunk {ci} failed rc={r.returncode}")
        preds = read_jsonl(cout / "predictions.jsonl")
        if len(preds) != len(sl):
            raise SystemExit(f"chunk {ci} returned {len(preds)} predictions for {len(sl)} prompts")
        meta = json.loads((cout / "GENERATE.json").read_text(encoding="utf-8"))
        per_chunk.append({"chunk": ci, "rows": len(sl),
                          "wall_seconds": round(time.time() - t0, 1),
                          "rows_skipped_context_overflow": meta["rows_skipped_context_overflow"],
                          "terminated_rows": meta["terminated_rows"]})
        merged.extend(preds)
        print(f"    {per_chunk[-1]['wall_seconds']}s", flush=True)

    # ---- merge checks: assertions, not warnings -------------------------------------------
    ids = [p["id"] for p in merged]
    if len(set(ids)) != len(ids):
        raise SystemExit("duplicate ids in merged predictions")
    if ids != [r["id"] for r in rows]:
        raise SystemExit("merged id order does not equal the prompts file order")

    if a.verify_against is not None:
        ref = {p["id"]: p.get("prediction", "") for p in read_jsonl(a.verify_against)}
        miss = [i for i in ids if i not in ref]
        if miss:
            raise SystemExit(f"{len(miss)} ids absent from the reference predictions")
        diff = [(p["id"], ref[p["id"]], p.get("prediction", ""))
                for p in merged if ref[p["id"]] != p.get("prediction", "")]
        shutil.rmtree(work)
        print(f"\nHARNESS VALIDATION on {len(merged)} rows against {a.verify_against}")
        print(f"  identical predictions : {len(merged) - len(diff)}/{len(merged)}")
        if diff:
            print(f"  DIVERGENT            : {len(diff)}")
            for i, x, y in diff[:10]:
                print(f"    {i}: ref={x!r}  got={y!r}")
            print("\nVERDICT: NOT REPRODUCED -- conditions differ; do not score arms with this "
                  "interpreter against the existing ladder")
            return 2
        print("\nVERDICT: REPRODUCED byte-for-byte -- harness and interpreter are matched")
        return 0

    a.out.mkdir(parents=True)
    with (a.out / "predictions.jsonl").open("w", encoding="utf-8", newline="\n") as f:
        for p in merged:
            f.write(json.dumps(p, ensure_ascii=False) + "\n")

    ok = [p for p in merged if p["status"] == "ok"]
    gen = sorted(p["generated_tokens"] for p in ok)
    last = json.loads((work / f"c{n_chunks - 1}" / "GENERATE.json").read_text(encoding="utf-8"))
    import torch  # noqa: PLC0415 -- recorded for provenance only
    import transformers  # noqa: PLC0415
    meta = {
        "label": a.label, "model": a.model, "rows": len(merged),
        "rows_skipped_context_overflow": sum(c["rows_skipped_context_overflow"]
                                             for c in per_chunk),
        "terminated_rows": sum(1 for p in ok if p["terminated"]),
        "max_new_tokens": a.max_new_tokens, "max_context": a.max_context, "dtype": a.dtype,
        "eos_ids": last["eos_ids"], "decoding": "greedy", "numerics": last["numerics"],
        "transformers": transformers.__version__,
        # recorded because the original manifest did not, and matched conditions are the
        # entire basis of every paired contrast this bank supports
        "torch": torch.__version__,
        "torch_cuda_build": getattr(torch.version, "cuda", None),
        "interpreter": a.python,
        "generator_sha256": sha256_file(a.generator),
        "generator_unmodified": True,
        "serving_path": last["serving_path"],
        "wall_seconds": round(time.time() - started, 1),
        "generated_tokens": ({"min": gen[0], "p50": gen[len(gen) // 2], "max": gen[-1]}
                             if gen else None),
        "generated_token_stats": "RECOMPUTED from merged predictions, not averaged",
        "prompts_file": str(a.prompts),
        "quality_claim": False, "release_permitted": False,
        "chunked_execution": {
            "chunk_size": a.chunk, "chunks": n_chunks, "per_chunk": per_chunk,
            "why": ("stage2_generate.py leaks across rows on this host: 64 rows succeed and 128 "
                    "fail at 7449 MiB free VRAM. Each chunk is a fresh process with identical "
                    "model, prompts, decoding, dtype and limits; only process boundaries differ."),
            "generator_unmodified": True,
            "merge_checks": ["no duplicate ids",
                             "merged id order equals the prompts file order",
                             "every chunk returned exactly as many predictions as prompts"],
        },
    }
    (a.out / "GENERATE.json").write_text(json.dumps(meta, indent=2) + "\n", encoding="utf-8")
    shutil.rmtree(work)
    print(f"\nwrote {a.out} -- {len(merged)} rows in {meta['wall_seconds']}s")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
